CSS+='''body{margin:0}.pg{position:relative;overflow:hidden}.px{padding:0 20px}.h{display:flex;align-items:center;justify-content:space-between;height:64px}.h1{font-size:var(--font-size-page);font-weight:700;line-height:1.3;margin:0}.h2{font-size:var(--font-size-section);font-weight:600;margin:24px 0 12px;display:flex;justify-content:space-between;align-items:baseline}.m{color:var(--color-text-muted);font-size:14px}.chips{display:flex;gap:8px;overflow:hidden;margin:12px -20px;padding:0 20px}.chip{flex:none;min-height:40px;padding:0 16px;border-radius:999px;border:1px solid var(--color-border);background:var(--color-surface);display:flex;align-items:center;font-size:14px}.chip.on{background:var(--color-text);color:var(--color-bg);border-color:var(--color-text);font-weight:600}.ro{display:flex;align-items:center;gap:12px;padding:12px 0;border-top:1px solid var(--color-border)}.ro:first-child{border:0}.ro>div{flex:1}.hero{background:#0B0B0D;color:#fff;border-radius:20px;padding:20px}.hero .m{color:#A9A9B2}.g{color:#F2D98D}
.sb{width:248px;flex:none;background:#0B0B0D;color:#fff;padding:24px 0}.sb img{width:150px;margin:0 24px 8px;display:block}.sb small{display:block;margin:0 24px 24px;color:#A9A9B2}.sb a{display:block;padding:12px 24px;color:#A9A9B2;font-size:16px}.sb a.on{color:#F2D98D;font-weight:600;background:#151519;border-inline-start:3px solid #D4AF37}.dsk{display:flex;height:100%}.mn{flex:1;min-width:0;padding:32px 40px}.tb{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.kp{display:grid;grid-template-columns:repeat(4,1fr);border-block:1px solid var(--color-border);margin-bottom:32px}.kp>div{padding:16px 24px;border-inline-start:1px solid var(--color-border)}.kp>div:first-child{border:0}.kp b{font-size:40px;font-weight:600;display:block;line-height:1.3}.tbl{width:100%;border-collapse:collapse}.tbl th{text-align:start;font-weight:500;font-size:14px;color:var(--color-text-muted);padding:8px 0}.tbl td{padding:12px 0;border-top:1px solid var(--color-border)}.cols{display:grid;gap:32px;grid-template-columns:1.4fr 1fr}.stp{display:flex;gap:12px;align-items:center;padding:8px 0;color:var(--color-text-muted)}.stp i{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-style:normal;font-weight:600;font-size:14px;border:1.5px solid var(--color-border)}.stp.on{color:var(--color-text);font-weight:600}.stp.on i{background:var(--color-accent);border-color:var(--color-accent);color:var(--color-on-accent)}.stp.dn i{background:var(--color-success);color:#fff;border-color:var(--color-success)}.note{display:flex;gap:8px;background:var(--color-info-bg);color:var(--color-info);border-radius:12px;padding:12px 16px;font-size:14px}.tab{display:inline-flex;gap:8px;margin:0 0 8px}.otp{display:flex;gap:8px;direction:ltr;justify-content:center}.otp span{width:48px;height:56px;border:1px solid var(--color-text-muted);border-radius:12px;display:grid;place-items:center;font-size:24px;font-weight:600}.otp .f{border-color:var(--color-focus);box-shadow:0 0 0 3px var(--color-info-bg)}.cta{position:absolute;inset-inline:0;bottom:0;padding:16px 20px;background:var(--color-surface);border-top:1px solid var(--color-border)}'''
