ic=lambda n,s='':f'<svg class="w-ico" viewBox="0 0 24 24" aria-hidden="true" style="{s}">{I[n]}</svg>'
dia='<svg viewBox="0 0 24 32" aria-hidden="true"><path d="M12 2l9 14-9 14-9-14z"/></svg>'
st=lambda n,h:f'<ol class="w-stamps w-num" style="--cols:{n}" aria-label="{h} من {n} أختام">'+''.join(f'<li class="{"on" if i<h else "off"}">{dia}<span>{i+1}</span></li>' for i in range(n))+'</ol>'
bd=lambda k,i,t:f'<span class="w-badge w-badge--{k}">{ic(i)}{t}</span>'
mark=lambda s=36:f'<img alt="وِثاق" src="data:image/png;base64,{LM}" style="height:{s}px">'
pr=lambda p:f'<div class="w-progress" role="progressbar" aria-valuenow="{p}" aria-valuemin="0" aria-valuemax="100"><i style="--p:{p}%"></i></div>'
def lc(m,l,n,sub,rt,body): return f'<div class="w-lcard" style="--m:{m}"><div class="w-lcard__head"><span class="w-logo">{l}</span><div style="flex:1"><b>{n}</b><div class="m">{sub}</div></div><span class="w-num" style="font-weight:700">{rt}</span></div><div style="margin-top:12px">{body}</div></div>'
def ro(m,l,t,s,b): return f'<div class="ro"><span class="w-logo" style="--m:{m};width:40px;height:40px">{l}</span><div><b>{t}</b><div class="m">{s}</div></div>{b}</div>'
def fld(l,inp,e=''): return f'<label class="w-field"><span>{l}</span>{inp}{e}</label>'
IN='class="w-input"'
def desk(items,active,title,sub,body,brand='لوحة التاجر'):
    s=''.join(f'<a href="#"{" class=\"on\"" if i==active else ""}>{t}</a>' for i,t in enumerate(items))
    return f'<div class="dsk"><aside class="sb"><img alt="وِثاق" src="data:image/png;base64,{LH}"><small>{brand}</small><nav aria-label="{brand}">{s}</nav></aside><main class="mn"><header class="tb"><div><h1 class="h1">{title}</h1><div class="m">{sub}</div></div></header>{body}</main></div>'
def page(t,b,w,h,theme=False):
    return ('<!doctype html>\n<html lang="ar" dir="rtl">\n<head>\n<meta charset="utf-8">\n<title>'+t+'</title>\n<script src="./support.js"></script>\n</head>\n<body>\n<x-dc>\n<helmet>\n<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&family=Inter:wght@500;600&display=swap">\n<style>'+CSS+'</style>\n</helmet>\n<div class="w-app pg" dir="rtl" '+('data-theme="dark" ' if theme else '')+f'style="width:{w}px;height:{h}px">'+b+'</div>\n</x-dc>\n<script type="text/x-dc" data-dc-script data-props=\'{"$preview":{"width":'+str(w)+',"height":'+str(h)+'}}\'>\nclass Component extends DCLogic {\nrenderVals() { return {}; }\n}\n</script>\n</body>\n</html>\n')
OUT='/mnt/user-data/outputs/artifacts/952c0811-4ec7-4af8-a624-aee605a996b0/project/'
def emit(boards):
    """boards: list of (file, title, w, h, theme, body, x, y). Writes files and merges canvas.json."""
    cj=json.load(open(OUT+'canvas.json'))
    for f,t,w,h,th,b,x,y in boards:
        open(OUT+f,'w',encoding='utf-8').write(page(t,b,w,h,th))
        cj['boards'][f]={'x':x,'y':y,'w':w,'h':h,'title':t}
        if f not in cj['order']: cj['order'].append(f)
    json.dump(cj,open(OUT+'canvas.json','w'),ensure_ascii=False,indent=2)
    return [OUT+f for f,*_ in boards]
